# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students to list")
    for pupil in students:
        if not pupil.email:
            raise ProjectError(
                f"no email for {pupil.display_name}"
            )


def _line(cells: Sequence[str], sizes: Sequence[int]) -> str:
    padded = [
        cell.ljust(size) for cell, size in zip(cells, sizes)
    ]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    _check(students)
    ordered = sorted(
        students, key=lambda pupil: pupil.display_name.lower()
    )
    table = [
        (pupil.display_name, pupil.section, pupil.email)
        for pupil in ordered
    ]
    sizes = [max(len(row[col]) for row in table) for col in range(3)]
    return [_line(row, sizes) for row in table]
EOF
